/**
 *  逐日聚合行（热力图数据源）。
 *  `estimated_tokens`：当日估算行（estimated=1，中转剥离 usage 按字符数兜底）
 *  的 prompt+completion 合计。0 表示当日全部为真实上报；前端据此提示「含估算值」，
 *  避免估算数字与真实统计混展时无法分辨。
 */
export type AiUsageDaily = {
	day: string,
	calls: number,
	prompt_tokens: number,
	completion_tokens: number,
	cache_hit_tokens: number,
	cache_miss_tokens: number,
	estimated_tokens: number,
};

/**
 *  按监控源聚合行（表格 / 饼图数据源）。`label` 为监控源本身的标识
 *  `owner/repo`（description 是用户备注，不作为统计维度的显示名）；
 *  `source_id` 为 None 表示无源调用（连接测试），前端以「无源」聚合展示。
 */
export type AiUsageSourceRow = {
	source_id: number | null,
	label: string | null,
	source_type: string | null,
	calls: number,
	prompt_tokens: number,
	completion_tokens: number,
	cache_hit_tokens: number,
	cache_miss_tokens: number,
};

/**  一次查询返回的全部聚合结果（热力图 + 表格 + 饼图共享同一份筛选条件）。 */
export type AiUsageStats = {
	daily: AiUsageDaily[],
	by_source: AiUsageSourceRow[],
	by_action: AiUsageActionRow[],
};

/**
 *  设置读写共用同一结构：get_settings 返回它，update_settings 直接接收它。
 *  前端 payload 与后端结构字段一一对应（snake_case），
 *  新增设置项只需改 AppSettings 一处 + get_settings/apply_settings 两处。
 */
export type AppSettings = {
	poll_interval_minutes: number,
	proxy_url: string,
	proxy_mode: string,
	auto_start: boolean,
	minimize_to_tray: boolean,
	log_retention_days: number,
	deepseek_enabled: boolean,
	deepseek_model: string,
	deepseek_base_url: string,
	/**  派生只读标志（凭据是否已设置），update_settings 忽略其值。 */
	deepseek_api_key_set: boolean,
	deepseek_proxy_bypass: boolean,
	deepseek_prompt: string,
	deepseek_min_importance: string,
	deepseek_translate_release: boolean,
	check_prereleases: boolean,
	fetch_history: boolean,
	fetch_history_count: number,
	language: string,
	theme: string,
	/**  界面缩放百分比（80–150，100 = 默认），应用为 WebView 页面缩放（set_zoom）。 */
	font_scale: number,
	show_source_type_icons: boolean,
	/**
	 *  是否显示 AI 重要度（大/中/小）徽标与筛选（默认关闭）：仅控制 UI 展示，
	 *  不影响 ai_importance 的生成与「按重要度通知」阈值逻辑。
	 */
	show_importance: boolean,
	enable_usage_stats: boolean,
	/**
	 *  自动标为已读的档位：`open`（默认：从列表打开详情弹窗时）/ `navigate`（打开与 ←/→ 翻页
	 *  都标记）/ `off`（不自动标记，打开发布页也不标）。未知值按 `off` 处理
	 *  （见 `db::settings::normalize_auto_read_detail`）。仅改写未读条目，已读/已忽略/
	 *  未到期的稍后提醒不动。
	 */
	auto_read_detail: string,
	github_token_set: boolean,
	youtube_api_key_set: boolean,
	bilibili_cookie_set: boolean,
};

/**
 *  点击桌面通知**主体**请求前端聚焦某条 release，payload 为 release id。
 *  与「前往」按钮区分：点主体只唤起窗口并定位，**不改通知状态**（语义为「去看一眼」，
 *  不代表已处理），因此不 emit ReleaseStateChanged，托盘红点与未读计数保持不变。
 */
export type FocusRelease = number;

/**
 *  日志表写入了新条目，前端据此刷新日志 tab。
 * 
 *  存在意义：后台 AI 批（摘要补全/翻译）是 fire-and-forget，可能在发起它的那轮
 *  轮询结束几分钟后才收尾写日志，仅靠 `PollCompleted` 驱动刷新会漏掉这些延迟
 *  到达的日志——用户不切走再切回日志 tab 就看不到。
 */
export type LogAppended = null;

export type LogEntry = {
	id: number,
	level: string,
	message: string,
	created_at: string,
	message_key: string | null,
	message_args: string | null,
	rendered_message: string | null,
};

export type LogSearchResult = {
	entries: LogEntry[],
	total: number,
	page: number,
	page_size: number,
};

/**  托盘菜单请求前端切换标签页，payload 为目标标签名。 */
export type Navigate = string;

/**  一次轮询完成（手动或定时），前端据此刷新列表与倒计时。 */
export type PollCompleted = null;

export type PollResult = {
	new_releases: ReleaseInfo[],
};

export type PruneAgentSessionsResult = {
	deleted: number,
	failed: number,
	failed_keys: string[],
};

export type ReleaseInfo = {
	id: number,
	source_id: number,
	source_type: string,
	owner: string,
	repo: string,
	tag_name: string,
	release_name: string,
	html_url: string,
	published_at: string,
	prerelease: boolean,
	body: string | null,
	detected_at: string,
	notification_status: string,
	snooze_until: string | null,
	ai_summary: string | null,
	ai_importance: string | null,
	body_translated: string | null,
	extra_metadata: string | null,
	/**  所属源的描述（YouTube 源存频道名），前端用于展示可读名称。 */
	source_description: string | null,
	/**  用户旗标：0 = 未标记，1-6 = 预设颜色（红/橙/黄/绿/蓝/紫），语义由用户自行赋予。 */
	flag: number,
	/**
	 *  相对同 source 上一版本（按 published_at）的 semver 变化类型：major/minor/patch。
	 *  无 semver tag 的源（YouTube/B 站等）或无法比较（相等/回落）时为 NULL。
	 */
	version_bump: string | null,
};

export type ReleaseSearchBody = {
	id: number,
	body: string | null,
	body_translated: string | null,
};

/**  release 状态变更（新增/已读/忽略/删除等），payload 为 release id（0 表示批量变更）。 */
export type ReleaseStateChanged = number;

/**
 *  单条 release 的流式翻译分片（用户在详情弹窗点「翻译」期间的增量译文）。
 * 
 *  只在手动单条翻译时发出：后台自动翻译批没有观察者，逐片发事件纯属白耗 IPC。
 *  前端按 `release_id` 过滤，只喂给当前正在展示的那条（并行时可能多条同时出字）。
 */
export type ReleaseTranslateChunk = {
	release_id: number,
	/**  本次新增的译文片段（**非全量**，前端累加）。 */
	delta: string,
};

export type RpcAvailableModel = {
	provider: string,
	id: string,
	name?: string | null,
};

export type Source = {
	id: number,
	source_type: string,
	owner: string,
	repo: string,
	poll_interval_minutes: number,
	enabled: boolean,
	last_checked_at: string | null,
	last_check_status: string,
	last_check_message: string | null,
	consecutive_failures: number,
	last_new_count: number,
	muted: boolean,
	created_at: string,
	updated_at: string,
	description: string | null,
	/**  源级附加配置（JSON）。目前用于 YouTube 订阅内容类型（视频/直播/帖子）。 */
	config: string | null,
};

/**  源因连续失败被自动禁用，payload 携带源信息供前端提示。 */
export type SourceAutoDisabled = {
	owner: string,
	repo: string,
	id: number,
	failures: number,
};

export type SourceTypeInfo = {
	source_type: string,
	auth_kind: string,
	ai_eligible: boolean,
	always_fetch_history: boolean,
	refresh_description_after_check: boolean,
};

export type TestDeepseekPayload = {
	model: string | null,
	baseUrl: string | null,
	apiKey: string | null,
	proxyBypass: boolean | null,
	proxyUrl: string | null,
	proxyMode: string | null,
};

/**
 *  检查更新的返回结构，字段与 tauri-plugin-updater 内部的 `commands::Metadata` 一致
 *  （含 camelCase 重命名），保证前端 `new Update(meta)` 直接可用。
 * 
 *  `raw_json` 走字符串传递：specta rc.25 对 `serde_json::Value` 的 Type 实现是
 *  递归内联的枚举（Array/Object 又引用回 Value），导出 TS 时会触发 inline cycle panic。
 *  前端 `JSON.parse` 还原即可（latest.json 很小，开销可忽略）。
 */
export type UpdaterMetadata = {
	rid: number,
	currentVersion: string,
	version: string,
	date: string | null,
	body: string | null,
	rawJson: string,
};

/**  单日计数（按本地时区 YYYY-MM-DD 分桶）。 */
export type UsageDaily = {
	day: string,
	count: number,
};

/**  单个事件的聚合统计行：total_count 为累计次数（SUM），daily 为按天趋势。 */
export type UsageStatRow = {
	key: string,
	total_count: number,
	last_day: string,
	daily: UsageDaily[],
};

/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

